{
  "name": "@sergemso/opencode-plugin",
  "version": "1.0.0",
  "description": "OpenCode TUI plugin rendering a @sergemso/statusline-core status line",
  "type": "module",
  "main": "dist/index.js",
  "types": "dist/index.d.ts",
  "exports": {
    ".": {
      "import": "./dist/index.js",
      "types": "./dist/index.d.ts"
    },
    "./plugin": {
      "import": "./src/plugin.tsx"
    },
    "./package.json": "./package.json"
  },
  "scripts": {
    "build": "tsc",
    "test": "vitest run",
    "dev": "tsc --watch"
  },
  "keywords": [
    "opencode",
    "statusline",
    "tui",
    "plugin"
  ],
  "author": "S. Strebulaev",
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "https://github.com/sergemso/ai-tools.agent-status-line.git",
    "directory": "packages/opencode-plugin"
  },
  "bugs": {
    "url": "https://github.com/sergemso/ai-tools.agent-status-line/issues"
  },
  "homepage": "https://github.com/sergemso/ai-tools.agent-status-line/tree/main/packages/opencode-plugin#readme",
  "publishConfig": {
    "access": "public",
    "registry": "https://registry.npmjs.org/"
  },
  "files": [
    "dist/",
    "README.md",
    "src/plugin.tsx"
  ],
  "dependencies": {
    "@sergemso/statusline-core": "^1.0.0"
  },
  "peerDependencies": {
    "@opencode/client": ">=2.0.0",
    "@opencode/plugin": ">=2.0.0",
    "@opentui/solid": ">=1.0.0",
    "solid-js": ">=1.8.0"
  },
  "peerDependenciesMeta": {
    "@opencode/plugin": {
      "optional": true
    },
    "@opencode/client": {
      "optional": true
    },
    "@opentui/solid": {
      "optional": true
    },
    "solid-js": {
      "optional": true
    }
  },
  "devDependencies": {
    "solid-js": "^1.9.17",
    "typescript": "^5.3.0",
    "vitest": "^1.0.0"
  }
}

/**
 * @statusline/opencode-plugin — OpenCode TUI plugin that renders a
 * @statusline/core status line into the prompt.footer.status slot.
 *
 * See README.md for installation and usage.
 */
// The TUI plugin entry (plugin.tsx) is excluded from the tsc build because
// it uses JSX types provided by the OpenCode host (@opentui/solid) at
// runtime. Import it directly from "./plugin.js" when running inside
// OpenCode:
//
//   import { createStatusLinePlugin } from "@statusline/opencode-plugin/plugin";
//
// The pure-logic modules below are fully typed and unit-tested.
export { adaptSession } from "./adapter.js";
export { renderStatusLine } from "./render.js";
export { ansiToSpans, spansToPlainText } from "./ansi.js";
//# sourceMappingURL=index.js.map
